var n=`0459-karn-yar-k`;var a=`world-0459`;var o=`TR`;var i=`western-asia`;var r=4;var l=68;var g={en:`Karnıyarık`,ua:`Карниярик`};var s={en:`A traditional dish from Türkiye, centered on eggplant, ground beef, yellow onion, red bell pepper. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: баклажан, яловичий фарш, жовта цибуля, червоний солодкий перець. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 24 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 24 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:24,i:[[`eggplant`,750,`g`],[`extra-virgin-olive-oil`,60,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ground-beef`,440,`g`],[`yellow-onion`,190,`g`],[`red-bell-pepper`,160,`g`],[`tomato`,330,`g`],[`garlic`,3,`clove`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:9,i:[]},{en:`Bake in a preheated 180°C oven for about 25 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 25 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:25,i:[[`tomato-passata`,200,`g`]]}];var d={slug:n,id:a,country:`TR`,region:i,servings:4,minutes:68,title:g,text:s,steps:u};export{o as country,d as default,a as id,l as minutes,i as region,r as servings,n as slug,u as steps,s as text,g as title};